INSERT INTO collection_pages VALUES('464b9a22220602f2606773f346c8089a3b4361ee3db38ea016aadbe2d1a09c2e','456276d4d8cee56f65c6a36ae6e353caa2e7e93d6a16c3a2e717c9b1f8d9c3ef','{"hasNext":false,"items":[{"author":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"authoredDate":"2026-06-28T18:28:54Z","committedDate":"2026-06-28T18:28:54Z","committer":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"observedAt":"2026-10-08T23:33:13.878Z","repositoryId":1283254703,"sha":"8e83d90733d782eaf9bff445480cbf91f6f148b6"}],"observedAt":"2026-10-08T23:33:13.878Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"comments_url":"https://api.github.com/repos/cordovaravi/Api-functioncall-by-model/commits/8e83d90733d782eaf9bff445480cbf91f6f148b6/comments","commit":{"author":{"date":"2026-06-28T18:28:54Z","email":"noreply@anthropic.com","name":"Claude"},"comment_count":0,"committer":{"date":"2026-06-28T18:28:54Z","email":"noreply@anthropic.com","name":"Claude"},"message":"Add embeddable AI function-calling micro frontend (React + Vite + llama.cpp / LFM 2.5)\n\nIntroduces a self-contained React + Vite micro frontend that adds an AI chat\nwith function calling, backed by the LFM 2.5 model served locally via\nllama.cpp''s OpenAI-compatible Chat Completions API.\n\nHighlights:\n- LlamaClient runs the full tool-call loop against POST /v1/chat/completions\n  (parses JSON-string arguments, feeds tool results back, bounded rounds).\n- Extensible ToolRegistry + built-in example tools (time, safe calculator,\n  mock weather); hosts can register their own functions via the `tools` prop.\n- AIFunctionPanel embeddable component + useAIChat hook with scoped styles.\n- Two embedding modes: Module Federation remote and an npm/library build,\n  plus a standalone dev playground (vite.config three-mode setup).\n- README documents launching llama-server with --jinja and both embed paths.\n\nCo-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01LhP1xM8zbnTzcws2eR8jh8","tree":{"sha":"6d9e74cb9f1948ae45332a0d85164beaac8287db","url":"https://api.github.com/repos/cordovaravi/Api-functioncall-by-model/git/trees/6d9e74cb9f1948ae45332a0d85164beaac8287db"},"url":"https://api.github.com/repos/cordovaravi/Api-functioncall-by-model/git/commits/8e83d90733d782eaf9bff445480cbf91f6f148b6","verification":{"payload":"tree 6d9e74cb9f1948ae45332a0d85164beaac8287db\nauthor Claude <noreply@anthropic.com> 1782671334 +0000\ncommitter Claude <noreply@anthropic.com> 1782671334 +0000\n\nAdd embeddable AI function-calling micro frontend (React + Vite + llama.cpp / LFM 2.5)\n\nIntroduces a self-contained React + Vite micro frontend that adds an AI chat\nwith function calling, backed by the LFM 2.5 model served locally via\nllama.cpp''s OpenAI-compatible Chat Completions API.\n\nHighlights:\n- LlamaClient runs the full tool-call loop against POST /v1/chat/completions\n  (parses JSON-string arguments, feeds tool results back, bounded rounds).\n- Extensible ToolRegistry + built-in example tools (time, safe calculator,\n  mock weather); hosts can register their own functions via the `tools` prop.\n- AIFunctionPanel embeddable component + useAIChat hook with scoped styles.\n- Two embedding modes: Module Federation remote and an npm/library build,\n  plus a standalone dev playground (vite.config three-mode setup).\n- README documents launching llama-server with --jinja and both embed paths.\n\nCo-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01LhP1xM8zbnTzcws2eR8jh8\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgrLzsfFISF4by8Q+FKz27YpkK1USsBB+m\namu1QkJnbDsAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5AAAAQOKIwPoi\nu4c8K+4sBvtzdhZoZatvz7qPaqNozqSsjwA/R9LjoOee2tsvAh4h0y3MDZQAnkeXSVWM9Tw2cHRp\nMAM=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2026-06-28T18:29:02Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"html_url":"https://github.com/cordovaravi/Api-functioncall-by-model/commit/8e83d90733d782eaf9bff445480cbf91f6f148b6","node_id":"C_kwDOTHzpr9oAKDhlODNkOTA3MzNkNzgyZWFmOWJmZjQ0NTQ4MGNiZjkxZjZmMTQ4YjY","parents":[],"sha":"8e83d90733d782eaf9bff445480cbf91f6f148b6","url":"https://api.github.com/repos/cordovaravi/Api-functioncall-by-model/commits/8e83d90733d782eaf9bff445480cbf91f6f148b6"}],"requestUrl":"https://api.github.com/repos/cordovaravi/Api-functioncall-by-model/commits?per_page=100&page=1&sha=8e83d90733d782eaf9bff445480cbf91f6f148b6&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A00%3A41.792Z"}');
