rified: esbuild build clean, `node --check dist/server.mjs` passes, bare\npackages external / local code bundled. Backend 515 tests pass, typecheck + lint\nclean.","tree":{"sha":"ca1dfda64aacc704b66c245c887bb635d58f0d34","url":"https://api.github.com/repos/Maiiaa30/ReconDashboard/git/trees/ca1dfda64aacc704b66c245c887bb635d58f0d34"},"url":"https://api.github.com/repos/Maiiaa30/ReconDashboard/git/commits/515243b02854d9bc74dc539836a95dcda7a58d46","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/46065883?v=4","events_url":"https://api.github.com/users/Maiiaa30/events{/privacy}","followers_url":"https://api.github.com/users/Maiiaa30/followers","following_url":"https://api.github.com/users/Maiiaa30/following{/other_user}","gists_url":"https://api.github.com/users/Maiiaa30/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Maiiaa30","id":46065883,"login":"Maiiaa30","node_id":"MDQ6VXNlcjQ2MDY1ODgz","organizations_url":"https://api.github.com/users/Maiiaa30/orgs","received_events_url":"https://api.github.com/users/Maiiaa30/received_events","repos_url":"https://api.github.com/users/Maiiaa30/repos","site_admin":false,"starred_url":"https://api.github.com/users/Maiiaa30/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Maiiaa30/subscriptions","type":"User","url":"https://api.github.com/users/Maiiaa30","user_view_type":"public"},"html_url":"https://github.com/Maiiaa30/ReconDashboard/commit/515243b02854d9bc74dc539836a95dcda7a58d46","node_id":"C_kwDOTJBoQtoAKDUxNTI0M2IwMjg1NGQ5YmM3NGRjNTM5ODM2YTk1ZGNkYTdhNThkNDY","parents":[{"html_url":"https://github.com/Maiiaa30/ReconDashboard/commit/1efc3995939c813fdbbe283a6776fe22745f2824","sha":"1efc3995939c813fdbbe283a6776fe22745f2824","url":"https://api.github.com/repos/Maiiaa30/ReconDashboard/commits/1efc3995939c813fdbbe283a6776fe22745f2824"}],"sha":"515243b02854d9bc74dc539836a95d